  raw = c("FE: species", "FE: island", "nobs", "r2.within"),
  clean = c("FE: Species", "FE: Island", "Observations", "Within R2"),
  fmt = c(0, 0, 0, 3)
)

modelsummary(
  models_ex,
  output = "tinytable",
  stars = c("*" = .1, "**" = .05, "***" = .01),
  coef_map = cm_ex,
  gof_map = gm_ex
) |>
  group_tt(j = list("Pooled OLS" = 2:3, "Fixed effects" = 4:5))
